CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,verified BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS verification(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,creator_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('personal','family')),revision BIGINT NOT NULL DEFAULT 1,dissolved BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS memberships(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('parent','adult','child','owner')),profile_id TEXT,revision BIGINT NOT NULL DEFAULT 1,active BIGINT NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,permissions TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,archived BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invitations(hash TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),email TEXT NOT NULL,role TEXT NOT NULL,profile_id TEXT REFERENCES profiles(id),issued_by TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL,used_by TEXT);
CREATE TABLE IF NOT EXISTS parent_changes(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),target_id TEXT NOT NULL,new_role TEXT NOT NULL,requested_by TEXT NOT NULL,approved_by TEXT,revision BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),owner_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('private','shared')),audience TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,deleted BIGINT NOT NULL DEFAULT 0,seq BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY REFERENCES records(id),title TEXT NOT NULL,completed BIGINT NOT NULL,assignment TEXT NOT NULL,assignees TEXT NOT NULL,review BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY REFERENCES records(id),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY REFERENCES records(id),name TEXT NOT NULL,currency TEXT NOT NULL,opening_minor BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY REFERENCES records(id),kind TEXT NOT NULL,amount_minor BIGINT NOT NULL,currency TEXT NOT NULL,date TEXT NOT NULL,label TEXT NOT NULL,account_id TEXT);
CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY REFERENCES records(id),from_id TEXT NOT NULL,to_id TEXT NOT NULL,sent_minor BIGINT NOT NULL,received_minor BIGINT NOT NULL,date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS budgets(id TEXT PRIMARY KEY REFERENCES records(id),name TEXT NOT NULL,currency TEXT NOT NULL,limit_minor BIGINT NOT NULL,period TEXT NOT NULL,start_on TEXT NOT NULL,end_on TEXT,rollover TEXT NOT NULL,participants TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY REFERENCES records(id),title TEXT NOT NULL,schedule TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shopping(id TEXT PRIMARY KEY REFERENCES records(id),name TEXT NOT NULL,items TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY REFERENCES records(id),profile_id TEXT NOT NULL REFERENCES profiles(id),amount_minor BIGINT NOT NULL,currency TEXT NOT NULL,label TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',movement_id TEXT REFERENCES records(id));
CREATE TABLE IF NOT EXISTS grants(record_id TEXT NOT NULL REFERENCES records(id),user_id TEXT NOT NULL REFERENCES users(id),can_edit BIGINT NOT NULL,PRIMARY KEY(record_id,user_id));
CREATE TABLE IF NOT EXISTS operations(user_id TEXT NOT NULL REFERENCES users(id),id TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS changes(seq BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),record_id TEXT,actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,count BIGINT NOT NULL,until_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS scoped_records ON records(workspace_id,seq);
CREATE TABLE IF NOT EXISTS task_progress(task_id TEXT NOT NULL REFERENCES tasks(id),profile_id TEXT NOT NULL REFERENCES profiles(id),completed BIGINT NOT NULL DEFAULT 0,approved BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(task_id,profile_id));
CREATE TABLE IF NOT EXISTS password_recovery(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
